 const params=new URLSearchParams(location.search);
 const scenes={desktop:['桌面体验','让截图属于边缘，让工作继续。'],control:['控制中心','即开即用，常用操作保持一眼可见。'],settings:['设置','完整自定义，清楚而从容。'],history:['截图历史','以画面找回画面。'],historyVariants:['历史双样式','当前视图与图像网格并排比较。'],onboarding:['首次使用','三步开始，说明留在需要它的地方。'],compare:['前后对照','真实原生基线与设计原型，分别注明证据。'],system:['设计系统','同一套比例、材质与状态语言。']};
 const samples=window.RiftSamples;
